PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
CREATE TABLE IF NOT EXISTS analyses(id TEXT PRIMARY KEY,snapshot TEXT NOT NULL,kind TEXT NOT NULL,complete INTEGER NOT NULL,partial INTEGER NOT NULL,created TEXT NOT NULL,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS current_analysis(singleton INTEGER PRIMARY KEY CHECK(singleton=1),analysis TEXT NOT NULL REFERENCES analyses(id));
CREATE TABLE IF NOT EXISTS manifests(analysis TEXT PRIMARY KEY REFERENCES analyses(id) ON DELETE CASCADE,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS blobs(hash TEXT PRIMARY KEY,path TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS nodes(analysis TEXT NOT NULL REFERENCES analyses(id) ON DELETE CASCADE,id TEXT NOT NULL,owner TEXT,label TEXT,kind TEXT,class TEXT,data TEXT NOT NULL,PRIMARY KEY(analysis,id));
CREATE INDEX IF NOT EXISTS idx_nodes_owner ON nodes(analysis,owner,id);
CREATE INDEX IF NOT EXISTS idx_nodes_kind ON nodes(analysis,kind,id);
CREATE TABLE IF NOT EXISTS relations(analysis TEXT NOT NULL REFERENCES analyses(id) ON DELETE CASCADE,id TEXT NOT NULL,source TEXT NOT NULL,target TEXT NOT NULL,type TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(analysis,id));
CREATE INDEX IF NOT EXISTS idx_rel_out ON relations(analysis,source,type,id);
CREATE INDEX IF NOT EXISTS idx_rel_in ON relations(analysis,target,type,id);
CREATE TABLE IF NOT EXISTS evidence(analysis TEXT NOT NULL REFERENCES analyses(id) ON DELETE CASCADE,id TEXT NOT NULL,relation TEXT NOT NULL,source TEXT,site TEXT,status TEXT,data TEXT NOT NULL,PRIMARY KEY(analysis,id));
CREATE INDEX IF NOT EXISTS idx_evidence_relation ON evidence(analysis,relation,id);
CREATE TABLE IF NOT EXISTS sites(analysis TEXT NOT NULL REFERENCES analyses(id) ON DELETE CASCADE,id TEXT NOT NULL,owner TEXT,source TEXT,status TEXT,data TEXT NOT NULL,PRIMARY KEY(analysis,id));
CREATE INDEX IF NOT EXISTS idx_sites_owner ON sites(analysis,owner,id);
CREATE TABLE IF NOT EXISTS sources(analysis TEXT NOT NULL REFERENCES analyses(id) ON DELETE CASCADE,id TEXT NOT NULL,script TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(analysis,id));
CREATE TABLE IF NOT EXISTS diagnostics(analysis TEXT NOT NULL REFERENCES analyses(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(analysis,ordinal));
CREATE VIRTUAL TABLE IF NOT EXISTS node_search USING fts5(analysis,id UNINDEXED,label,tokenize='unicode61');
PRAGMA user_version = 1;
